    slug: "affinity",
    name: "Affinity",
    description: "Fashionable in the 1920s, the Affinity first appears in The New York Sun on Monday 28th October 1907. There's another new cocktail on Broadway. They call it the Affinity. After drinking one, surviving experimenters declare, the horizon takes on a roseate hue; the second brings Wall Street to the front and centre proffering to you a quantity of glistening lamb Shearings; when you've put away the third the green grass grows up all around, birds sing in the fig trees and your affinity appears. The new ambrosia contains three ingredients: One medium teaspoon of powdered sugar, one dash of orange bitters, on jigger of Scotch whiskey and half a jigger of Italian vermouth. These are shaken in cracked ice, cocktail fashion, until thoroughly blended and cooled hen strained and quickly serv",
