    description: "A \"Plantation Alamagoozlum\" is referenced as \"an excellent preventive of colds and chills\" in a 1935 column in The Indianapolis News and then as an Alamagoozlum in a 1937 edition of the Louisville, Kentucky, Courier-Journal . However, it most notably features in Charles H. Baker's 1939 The Gentleman's Companion: Around the World with Jigger, Beaker and Flask as \"J. Pierpont Morgan's Alamagoozlum, the Personal Mix Credited to that Financier, Philanthropist, & Banker of a Bygone Era.\" Baker gives the following recipe \"To serve about 5 cocktails: take 1 jigger each of Jamaica rum, gomme syrup, and yellow or green Chartreuse; add \u00bd pony yellow Cura\u00e7ao and \u00bd pony of Angostura bitters. Add 2 scant ponies of Holland gin, the same of water; donate \u00bd the white of an egg and hard shake with",
