    id: "3cc6960b-aadc-49b8-a0e1-4b1c0935ff4e",
    slug: "aunt-agatha",
    name: "Aunt Agatha",
    description: "Aunt Agatha was Bertie Wooster's terrifying aunt in P.G. Wodehouse's books. Adapted from a recipe in Victor Bergeron 's 1972 Trader Vic's Bartender's Guide, Revised . AUNT AGATHA. 1\u00bd ounces light Puerto Rican rum 2 ounces orange juice Angostura bitters Pour rum and orange juice over ice cubes in old fashioned glass. Stir. Float a few drops of bitters on top. Variation: Substitute grapefruit juice for orange juice Victor Bergeron, Trader Vic's Bartender's Guide, 1972 More cocktails by Victor Bergeron A.K.A",
    image_url: "https://cdn.diffordsguide.com/cocktail/wrNypA/square/0/512x512.webp?v=1743685285",
    origin: "",
    base: [],
    modifiers: [],
