    garnish: "",
    tags: ["intermediate"],
    story: "Aunt Agatha was Bertie Wooster's terrifying aunt in P.G. Wodehouse's books. Adapted from a recipe in Victor Bergeron 's 1972 Trader Vic's Bartender's Guide, Revised . AUNT AGATHA. 1\u00bd ounces light Puerto Rican rum 2 ounces orange juice Angostura bitters Pour rum and orange juice over ice cubes in old fashioned glass. Stir. Float a few drops of bitters on top. Variation: Substitute grapefruit juice for orange juice Victor Bergeron, Trader Vic's Bartender's Guide, 1972 More cocktails by Victor Bergeron A.K.A",
